def transform(grid):
    h,w=len(grid),len(grid[0])
    divrow=next((r for r,row in enumerate(grid) if len(set(row))==1 and row[0] == 3),None)
    if divrow is not None:
        a,b=grid[:divrow],grid[divrow+1:]
    else:
        divcol=next(c for c in range(w) if all(row[c]==grid[0][c]!=0 for row in grid))
        a=[row[:divcol] for row in grid]; b=[row[divcol+1:] for row in grid]
    def bg(panel):
        counts={}
        for row in panel:
            for v in row: counts[v]=counts.get(v,0)+1
        return max(counts,key=counts.get)
    ba,bb=bg(a),bg(b)
    return [[2 if x!=ba and y!=bb else 0 for x,y in zip(ra,rb)] for ra,rb in zip(a,b)]

